#!/usr/bin/env node
// Embarque le générateur de cartes dans l'éditeur (installer.html), entre les
// marqueurs <!-- card-art:begin --> et <!-- card-art:end -->.
// Le navigateur dessine alors la carte de n'importe quelle console à la demande :
//   CardArt.render(system, variant, { uniformSpine })  ->  { svg, zones }
//   variant : 'h-right' | 'h-left' | 'v' ; zones en 0,1 mm.
// À relancer après toute modification de lib/ ou de themes.js :
//   node cards/bundle.js

const fs = require('fs');
const path = require('path');

const here = __dirname;
const target = path.join(here, '..', 'installer.html');
const modules = { color: 'lib/color.js', heroes: 'lib/heroes.js', details: 'lib/details.js', card: 'lib/card.js', themes: 'themes.js' };

let code = '';
for (const [name, file] of Object.entries(modules)) {
  const src = fs.readFileSync(path.join(here, file), 'utf8').replace(/^#!.*\n/, '');
  if (/<\/script/i.test(src)) throw new Error(file + ' contient </script');
  code += `M[${JSON.stringify(name)}] = (function (module, exports) {\n${src}\nreturn module.exports;\n})({ exports: {} }, {});\n`;
}

const api = `
const { card } = M.card;
const THEMES = M.themes;
/* Console without a theme of its own: a neutral black card. */
const GENERIC = {
  name: '', short: '', body: ['#2a2a2f', '#1b1b1f', '#0e0e10'], texture: { type: 'grid', color: '#3a3a3f', fade: true },
  hero: { type: 'disc', base: '#141416', lid: '#26262b', hub: '#111' },
  aux1: { type: 'vents' }, aux2: { type: 'power', volume: false },
  spine: { bg: '#101012', texture: 'grid' },
};
/* Recalbox system ids that differ from the theme names. */
const ALIASES = {
  gb: 'gameboy', gbc: 'gameboycolor', gba: 'gameboyadvance', n64: 'nintendo64', '64dd': 'nintendo64dd',
  fds: 'famicomdisksystem', sufami: 'sufamiturbo', gw: 'gameandwatch', segacd: 'megacd', psx: 'playstation1',
  ps2: 'playstation2', jaguar: 'atarijaguar', o2em: 'videopac', wswan: 'wonderswan', wswanc: 'wonderswancolor',
  c64: 'commodore64', x68000: 'sharpx68000', x1: 'sharpx1', bk: 'elektronikabk', mac: 'macintosh', coco: 'trs80coco',
};
const themeOf = (system) => THEMES[ALIASES[system] || system];
const SIDES = { 'h-right': 'right', 'h-left': 'left', v: 'bottom' };
const cache = new Map();
return {
  has: (system) => Boolean(themeOf(system)),
  /* Names written on the card: console (logo place) and short name (tab). */
  info(system) {
    const theme = themeOf(system) || GENERIC;
    return { name: theme.name || '', short: theme.short || '' };
  },
  /* The Mega Drive tab, used on every card when uniformSpine is set. */
  uniformSpine: THEMES.megadrive.spine,
  render(system, variant, opts) {
    const uniform = Boolean(opts && opts.uniformSpine);
    const key = system + '|' + variant + '|' + uniform;
    if (!cache.has(key)) {
      const theme = themeOf(system) || GENERIC;
      /* square: the editor rounds the card itself (two roundings leave a light edge). */
      cache.set(key, card(theme, SIDES[variant] || 'right', Object.assign({ square: true }, uniform ? { spine: THEMES.megadrive.spine } : {})));
    }
    return cache.get(key);
  },
};`;

const block = `<!-- card-art:begin (generated by cards/bundle.js, do not edit) -->
<script>
const CardArt = (function () {
"use strict";
const M = {};
const require = (name) => M[name.replace(/^.*\\//, '')];
${code}${api}
})();
</script>
<!-- card-art:end -->`;

const html = fs.readFileSync(target, 'utf8');
const re = /<!-- card-art:begin[\s\S]*?<!-- card-art:end -->/;
if (!re.test(html)) throw new Error('marqueurs card-art absents de installer.html');
fs.writeFileSync(target, html.replace(re, () => block));
console.log('installer.html : générateur de cartes embarqué (' + Math.round(block.length / 1024) + ' Ko)');
